# Code generated by AI (Claude Sonnet 5.5)

import json
import sys

def main():
    text = sys.stdin.read()

    # empty output keeps chezmoi from creating a config the tool never wrote
    if not text.strip():
        return

    lines = text.splitlines()
    wanted = json.loads(r'''{{ toJson .set }}''')

    # only top-level scalar keys are rewritten in place, so comments, nested maps and key order stay untouched
    seen = set()
    for index, line in enumerate(lines):
        key, sep, _ = line.partition(":")
        if sep and key in wanted:
            lines[index] = f"{key}: {wanted[key]}"
            seen.add(key)

    lines.extend(f"{key}: {wanted[key]}" for key in sorted(wanted.keys() - seen))
    sys.stdout.write("\n".join(lines) + "\n")

if __name__ == "__main__":
    main()
